"""Cross-checks quoted in lessons 13-28 for Colgate-Palmolive.

Run from the company folder:
  python3 modules-2-4-cross-checks.py > modules-2-4-cross-checks-output.md

Nothing here changes the ledger or the model. Each number is arithmetic on the ledger, the model's own
functions, or a named file in sources/ or professor-spreadsheet/, that a lesson answer quotes.
"""
import csv, importlib.util, json, re, statistics
import yaml

L = yaml.safe_load(open("inputs.yaml"))
spec = importlib.util.spec_from_file_location("model", "../../../../.claude/skills/value-company/tools/model.py")
M = importlib.util.module_from_spec(spec); spec.loader.exec_module(M)
FACTS = "sources/filings/cl-multi-year-financials-fy2014-fy2025.tsv"
PRICES = "sources/market-data/cl-vs-sp500-monthly-2020-12-to-2026-11.tsv"
COMPS = "sources/capital-iq/quick-comps.tsv"

c = L["company"]; m = L["market"]
v = lambda k: c[k]["value"]
rf, bond, t = m["risk_free_rate"]["value"], m["govt_bond_rate"]["value"], m["tax_rate_marginal"]["value"]
mature, erp, g = m["mature_erp"]["value"], L["country"]["weighted_erp"]["value"], m["terminal_growth"]["value"]
D, E, bu = v("debt_total"), v("equity_value"), L["beta"]["unlevered_bottom_up"]["value"]
V = D + E
kd = bond + 0.0070
ebit, da, capex, dwc = v("ebit"), v("da"), v("capex"), v("change_wc")
ic, gw, rev = v("invested_capital"), v("goodwill"), v("revenue")
shares, price = v("shares_basic"), v("share_price")
pct = lambda x, n=2: f"{x * 100:.{n}f}%"
mny = lambda x: f"{x:,.0f}"

facts = {}
for row in csv.reader(open(FACTS), delimiter="\t"):
    if row[0] == "taxonomy":
        hdr = row; continue
    facts[row[1]] = {int(y): float(x) for y, x in zip(hdr[3:], row[3:]) if x != ""}
F = lambda tag, y: facts[tag][y] / 1e6

print('---\ntitle: "Colgate-Palmolive (CL) — Modules 2 to 4 cross-checks"\nstatus: draft\nowner: weprintmoney\ncreated: 2026-11-21\nlast_updated: 2026-11-21\n---\n')
print("# Modules 2 to 4 cross-checks (lessons 13 to 28)\n\nGenerated by `modules-2-4-cross-checks.py` from `inputs.yaml`, the model's own functions, and files in `sources/` and `professor-spreadsheet/`. Do not edit by hand. Amounts in $ millions.\n")

# ------------------------------------------------------------ 1. weights
print("## 1. Weights and divisional debt (lesson 13)\n")
dm, lease = v("debt_market"), v("lease_debt")
bookD = v("debt_book") + lease; bookE = v("equity_book")
print("| Item | Value |\n|---|---|")
print(f"| Market debt ratio with leases | {pct(D / V)} |")
print(f"| Market debt ratio without leases ({mny(dm)} over {mny(dm + E)}) | {pct(dm / (dm + E))} |")
print(f"| Leases as a share of total debt | {pct(lease / D)} |")
print(f"| Book debt with leases | {mny(bookD)} |")
print(f"| Book debt ratio ({mny(bookD)} over {mny(bookD + bookE)}) | {pct(bookD / (bookD + bookE))} |")
print(f"| Market value of equity over book value | {E / bookE:,.0f} times |")
segs = L["beta"]["segments"]
ind_dc = {"Household Products": 0.1536, "Food Processing": 0.3043}   # market debt to capital, country-risk-regions-2026-01-01.md
op_share = {"Oral, Personal and Home Care": 3959 / (3959 + 1064), "Hill's Pet Nutrition": 1064 / (3959 + 1064)}  # 10-K note 14
raw = sum(op_share[s["name"]] * ind_dc[s["industry"]] for s in segs)
scale = (D / V) / raw
print(f"\nNo debt is issued by or disclosed for either segment. Two allocations:\n")
print("| Segment | Share of segment operating profit | Industry market debt to capital | Allocation A: company ratio | Allocation B: industry ratios scaled to the company's debt |")
print("|---|---|---|---|---|")
alloc = {}
for s in segs:
    b = ind_dc[s["industry"]] * scale; alloc[s["name"]] = b
    print(f"| {s['name']} | {pct(op_share[s['name']])} | {pct(ind_dc[s['industry']])} | {pct(D / V)} | {pct(b)} |")
print(f"\nValue-weighted industry ratio {pct(raw)}; scaling factor {scale:.4f} so the two segments add back to {pct(D / V)}. Sales-weighted industry ratio {pct(sum(s['weight'] * ind_dc[s['industry']] for s in segs))}.\n")
print("| Segment | Debt ratio (B) | Debt to equity | Levered beta | Cost of equity | Cost of capital | Cost of capital under allocation A |")
print("|---|---|---|---|---|---|---|")
for s in segs:
    d = alloc[s["name"]]; de = d / (1 - d); bl = s["unlevered_beta"] * (1 + (1 - t) * de); ke = rf + bl * erp
    w = (1 - d) * ke + d * kd * (1 - t)
    blA = s["unlevered_beta"] * (1 + (1 - t) * D / E); keA = rf + blA * erp; wA = (E / V) * keA + (D / V) * kd * (1 - t)
    print(f"| {s['name']} | {pct(d)} | {de:.4f} | {bl:.4f} | {pct(ke)} | {pct(w)} | {pct(wA)} |")

