# ------------------------------------------------------------ 10. FCFE
print("## 10. Free cash flow to equity, year by year, on the `dividends.xlsx` definition (lesson 26)\n")
print("Net income + depreciation, amortization and non-cash write-downs − capital spending and acquisitions − change in working capital + net debt issued. Inputs are the rows entered in the workbook (`professor-spreadsheet/inputs.md`). Option proceeds from the SEC data file.\n")
rows = []
for line in open("professor-spreadsheet/inputs.md"):
    if re.match(r"\| 20\d\d \| ", line):
        p_ = [x.strip().replace(",", "").replace("−", "-") for x in line.strip().strip("|").split("|")]
        rows.append([int(p_[0])] + [float(x) for x in p_[1:8]])
opt = {2018: 329, 2019: 498, 2020: 874, 2021: 424, 2022: 418, 2023: 380, 2024: 638, 2025: 101}
print("| Year | Net income | FCFE before debt | Net debt issued | FCFE | Dividends | Buybacks | Cash returned | Returned − FCFE | Returned ÷ FCFE | Option proceeds | Gap net of option proceeds |\n|---|---|---|---|---|---|---|---|---|---|---|---|")
tot = [0] * 8; tot5 = [0] * 8
for y, ni, dan, cx, wc, nd, dv, bb in sorted(rows):
    pre = ni + dan - cx - wc; fcfe = pre + nd; ret = dv + bb
    vals = [ni, pre, nd, fcfe, dv, bb, ret, opt[y]]
    tot = [a + b for a, b in zip(tot, vals)]
    if y >= 2021: tot5 = [a + b for a, b in zip(tot5, vals)]
    print(f"| {y} | {mny(ni)} | {mny(pre)} | {mny(nd)} | {mny(fcfe)} | {mny(dv)} | {mny(bb)} | {mny(ret)} | {mny(ret - fcfe)} | {pct(ret / fcfe)} | {opt[y]} | {mny(ret - fcfe - opt[y])} |")
for lab, x in (("2018–2025", tot), ("2021–2025", tot5)):
    print(f"| **{lab}** | **{mny(x[0])}** | **{mny(x[1])}** | **{mny(x[2])}** | **{mny(x[3])}** | **{mny(x[4])}** | **{mny(x[5])}** | **{mny(x[6])}** | **{mny(x[6] - x[3])}** | **{pct(x[6] / x[3])}** | **{mny(x[7])}** | **{mny(x[6] - x[3] - x[7])}** |")
print(f"\nEight-year gap net of option proceeds as a share of cash returned: {pct((tot[6] - tot[3] - tot[7]) / tot[6], 1)}; five-year: {pct((tot5[6] - tot5[3] - tot5[7]) / tot5[6], 1)}. Buybacks net of option proceeds: {mny(tot[5] - tot[7])} over eight years, {mny(tot5[5] - tot5[7])} over five. Cash returned against FCFE before debt, eight years: {pct(tot[6] / tot[1])}.")
c17, c20, c25 = F("CashAndCashEquivalentsAtCarryingValue", 2017), F("CashAndCashEquivalentsAtCarryingValue", 2020), F("CashAndCashEquivalentsAtCarryingValue", 2025)
print(f"Cash and equivalents: {mny(c17)} at the end of 2017, {mny(c20)} at the end of 2020, {mny(c25)} at the end of 2025: a change of {mny(c25 - c17)} over eight years and {mny(c25 - c20)} over five. Acquisitions inside the capital spending column: 3,894 over the eight years, {pct(3894 / tot[6], 1)} of cash returned. With acquisitions left out of the formula the eight-year FCFE would be {mny(tot[3] + 3894)} and cash returned {pct(tot[6] / (tot[3] + 3894))} of it.")
print(f"Five years, 2021–2025: cash returned net of option proceeds {mny(tot5[6] - tot5[7])}; FCFE plus option proceeds {mny(tot5[3] + tot5[7])}. Eight years: FCFE before debt covers dividends {tot[1] / tot[4]:.2f} times; option proceeds are {pct(tot[7] / (tot[6] - tot[3]), 0)} of the gross gap.")
print(f"The model's section 5 leaves acquisitions out and covers 2023 to 2025: returned 9,438 against 8,204, {pct(9438 / 8204)}. The only acquisition in those years is 293 in 2025: 3,005 − 293 = 2,712, the 2025 row above.\n")

